/** Typed client for the FastAPI backend. Types in api.types.ts are generated by `make types`. */
export const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "http://localhost:8000";

export class ApiError extends Error {
  constructor(public status: number, message: string) {
    super(message);
  }
}

export async function api<T>(path: string, init?: RequestInit & { timeoutMs?: number }): Promise<T> {
  const ctrl = new AbortController();
  const t = setTimeout(() => ctrl.abort(), init?.timeoutMs ?? 8000);
  try {
    const res = await fetch(`${API_URL}${path}`, { ...init, signal: ctrl.signal, headers: { "content-type": "application/json", ...(init?.headers ?? {}) } });
    if (!res.ok) throw new ApiError(res.status, `${res.status} ${res.statusText} for ${path}`);
    return (await res.json()) as T;
  } finally {
    clearTimeout(t);
  }
}

export interface Health {
  ok: boolean;
  demoMode: boolean;
  mode: "live" | "replay";
}
